import {DOORS} from './data.js';
export function loadingOccupied(s){const d=DOORS.loading;return[s.player,...(s.actors||[]).filter(a=>a.mode!=='dead'),...(s.threats||[]).filter(a=>a.mode!=='dead'),...(s.crates||[]).filter(c=>['floor','warehouse'].includes(c.place))].some(a=>Math.abs(a.x-d.x)<d.w/2+.32&&Math.abs(a.z-d.z)<.65);}
export function requestLoading(g,open,manual=false){const s=g.s;if(s.loadingBroken)return false;if(!s.power&&!manual){g.notice('停电了，使用门边的应急手拉链。');return false;}if(open&&s.barricades.loading){g.notice('先对准门内木板按 E 拆除加固，再升门。');return false;}s.loadingTarget=open;s.loadingManual=manual;s.loadingStopped=false;g.sound(manual?'metalKey':'rearOpen',{pos:DOORS.loading});g.notice(open?'卷帘门正在升起。':'卷帘门正在下降；门口有人或货箱时会自动停住。');return true;}
export function tickLoading(s,dt,sound=()=>{}){if(s.loadingLift==null)s.loadingLift=s.doors.loading?1:0;if(s.loadingTarget==null)s.loadingTarget=!!s.doors.loading;if(s.loadingBroken){s.loadingLift=1;s.doors.loading=true;return;}if(!s.power&&!s.loadingManual)return;const want=s.loadingTarget?1:0,last=s.loadingLift;if(want<last&&loadingOccupied(s)){if(!s.loadingStopped)sound('doorLatch',{pos:DOORS.loading});s.loadingStopped=true;return;}s.loadingStopped=false;s.loadingLift=Math.max(0,Math.min(1,last+Math.sign(want-last)*dt*(s.loadingManual?.40:.72)));s.doors.loading=s.loadingLift>.74;if((last===0&&s.loadingLift>0)||(last===1&&s.loadingLift<1))sound('rearOpen',{pos:DOORS.loading});}
